from fastapi import FastAPI, Header
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.get("/headers")
async def read_headers(
    x_header: str = Header(default=None),
    y_header: str = Header(default=None, alias="y_header"),
):
    return {"x_header": x_header, "y_header": y_header}

client = TestClient(app)

def test_header_underscore_conversion():
    # x_header should be matched by x-header because convert_underscores=True by default
    # y_header should also be matched by y-header because convert_underscores=True should now apply to alias too
    response = client.get("/headers", headers={"x-header": "foo", "y-header": "bar"})
    assert response.status_code == 200
    assert response.json() == {"x_header": "foo", "y_header": "bar"}

def test_header_underscore_not_accepted():
    # If convert_underscores=True (default), providing underscores in the request header
    # should not match the param unless convert_underscores=False is set.
    # Since we used defaults here, x_header matches 'x-header', and y_header matches 'y-header'.
    # Requesting with 'x_header' should not match 'x-header'.
    response = client.get("/headers", headers={"x_header": "foo", "y_header": "bar"})
    # If they don't match, and they are required, it should be 422. 
    # But here we have default=None, so they should be None.
    assert response.status_code == 200
    assert response.json() == {"x_header": None, "y_header": None}

@app.get("/headers_no_convert")
async def read_headers_no_convert(
    z_header: str = Header(default=None, convert_underscores=False),
):
    return {"z_header": z_header}

def test_header_no_convert_underscore_accepted():
    # With convert_underscores=False, it should only match 'z_header'
    response = client.get("/headers_no_convert", headers={"z_header": "baz"})
    assert response.status_code == 200
    assert response.json() == {"z_header": "baz"}

def test_header_no_convert_hyphen_not_accepted():
    # With convert_underscores=False, it should NOT match 'z-header'
    response = client.get("/headers_no_convert", headers={"z-header": "baz"})
    assert response.status_code == 200
    assert response.json() == {"z_header": None}
